import type { DecodedForumText } from './forumContentCodec'
import { decodeForumText } from './forumContentCodec'

function summarize(text: string): string {
  return `${text.trim().substring(0, 12)}...`
}

export function buildPublishedTopicTitle(type: 'BUG' | 'FEAT' | 'ANN', title: string, text: string): string {
  return `${type}:${title.length === 0 ? summarize(decodeForumText(text).text) : title}`
}

/** Repair only the exact title generated by the old JSON-truncating publisher. */
export function normalizeForumTopicTitle(title: string, content: DecodedForumText): string {
  if (content.kind === 'tiptap' && title === `${JSON.stringify(content.doc).substring(0, 12)}...`)
    return summarize(content.text)
  return title
}
